INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷259", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。疑似转录讹字保留并单独注明。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/tongjian/259.txt", "note": "卷259乾宁元年条；书、卷、年、段落及行号见批次账本。", "id": "ee2a8086-0e0a-5257-8fa6-23127b09f219"}, {"title": "新五代史·卷66·楚世家·取潭州段", "source_type": "primary", "author": "欧阳修", "edition": "仓库PDF派生电子文本；逐字及换行保留，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/19%E6%96%B0%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L1427", "note": "原PDF第1427页；只补乾宁元年龙回关与取潭州，同页后事尚未推进。", "id": "6223a511-2e29-51e6-bbd3-de7759e83058"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "张从晦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：张从晦。", "biography": null, "status": "draft", "id": "7c3ecc4a-744e-5268-9420-c0e6a7f380bf"}, {"name": "江彦温", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：江彦温。", "biography": null, "status": "draft", "id": "dd50e2ae-3926-50de-b6d4-fcb987dd1cb4"}, {"name": "江从顼", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：江从顼。", "biography": null, "status": "draft", "id": "58db67a4-3371-5760-9684-dfcbfdfd2785"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "刘建锋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：刘建锋。", "biography": null, "status": "draft", "id": "084d26d2-8aae-5f9d-9127-ca3c97b203b6"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "邓处讷", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：邓处讷。", "biography": null, "status": "draft", "id": "53fdc66b-d182-5faf-896e-04db37e18b62"}, {"name": "蒋勋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：蒋勋。", "biography": null, "status": "draft", "id": "05f4879b-c4c4-5c94-9608-e880d6142ce2"}, {"name": "邓继崇", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：邓继崇。", "biography": null, "status": "draft", "id": "cb875892-5dc4-528a-835d-d8f43077fc40"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "王宗勉", "aliases": ["赵章"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：王宗勉。", "biography": null, "status": "draft", "id": "ee908f18-c08e-548f-8346-981303a02d43"}, {"name": "王先成", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：王先成。", "biography": null, "status": "draft", "id": "94dd1489-7123-5271-8334-319a776d16cc"}, {"name": "杨晟", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杨晟。", "biography": null, "status": "draft", "id": "93faf005-49ad-5fd8-82c5-75a556805ef0"}, {"name": "王宗训", "aliases": ["王茂权"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：王宗训。", "biography": null, "status": "draft", "id": "c8ad409d-be2e-57f4-b673-dbb94aee87ab"}, {"name": "安师建", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：安师建。", "biography": null, "status": "draft", "id": "8f38a8f9-9afe-5781-893f-790b48ff15f4"}, {"name": "王宗谨", "aliases": ["王钊"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：王宗谨。", "biography": null, "status": "draft", "id": "090e9957-0a8b-5aac-86b0-7ab10a3417c7"}, {"name": "王宗绾", "aliases": ["李绾"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：王宗绾。", "biography": null, "status": "draft", "id": "9f4f04b7-25f8-5d68-923c-abdb1d23a2c6"}, {"name": "郑延昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：郑延昌。", "biography": null, "status": "draft", "id": "33cc9170-06f5-5723-acfc-e8a8f3f1016e"}, {"name": "朱瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑄。", "biography": null, "status": "draft", "id": "dcaf5869-c45e-5845-b02f-6418dd1f22eb"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "安福顺", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：安福顺。", "biography": null, "status": "draft", "id": "ef311451-685f-5b56-a5a1-f3b40c71af33"}, {"name": "安福庆", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：安福庆。", "biography": null, "status": "draft", "id": "145805f3-22f4-545e-b40b-fc49202d276c"}, {"name": "安福迁", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：安福迁。", "biography": null, "status": "draft", "id": "2b6acadc-31ae-5842-ab22-c51982a98490"}, {"name": "杜洪", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的杜洪，在此段中为逐刺史并取代者。", "biography": null, "status": "draft", "id": "9091e17c-39e3-5f00-8d0f-e054c1147b48"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5