INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱全忠遣张从晦慰抚寿州", "start_year": 894, "end_year": 894, "time_original": "894年三月条后、五月条前；具体日未载", "dynasty": "唐", "description": "朱全忠派军将张从晦到寿州慰抚。张从晦凌侮刺史江彦温，又同诸将夜饮。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "82a39866-0d29-5f71-ab8f-631195405e8c"}, {"title": "江彦温疑谋己，杀夜饮诸将后自杀", "start_year": 894, "end_year": 894, "time_original": "张从晦夜饮的次日；894年，确日未载", "dynasty": "唐", "description": "江彦温怀疑夜饮诸将谋害自己，次日杀掉在席诸将，写信向朱全忠谢罪后自杀。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "417ea387-a75e-5f12-ba10-7cc0dcaf3f28"}, {"title": "寿州军推江从顼知军州事", "start_year": 894, "end_year": 894, "time_original": "江彦温自杀后；具体日未载", "dynasty": "唐", "description": "寿州军中推江彦温之子江从顼暂管军州事务。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "10d2a582-6a60-5363-9ed7-286384f66bf7"}, {"title": "朱全忠为寿州事腰斩张从晦", "start_year": 894, "end_year": 894, "time_original": "江彦温自杀与军推其子后；具体日未载", "dynasty": "唐", "description": "寿州内变后，朱全忠将张从晦腰斩。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "7e2d77b5-173b-507a-b9b4-bf9c89e28923"}, {"title": "钱镠加同平章事", "start_year": 894, "end_year": 894, "time_original": "894年五月", "dynasty": "唐", "description": "镇海节度使钱镠加同平章事。", "phases": [], "location_name": "镇海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dfd290fc-72a0-5dfa-b2ca-e96a71561277"}, {"title": "刘建锋马殷至澧陵，邓处讷派三千守关", "start_year": 894, "end_year": 894, "time_original": "894年五月条；具体日未载", "dynasty": "唐", "description": "刘建锋、马殷带兵到澧陵；邓处讷派邵州指挥使蒋勋、邓继崇率步骑三千守龙回关。", "phases": [], "location_name": "澧陵、龙回关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d02cd895-9105-55e0-a04e-a0f05e4763b0"}, {"title": "马殷遣使劝蒋勋归降，守兵弃甲散去", "start_year": 894, "end_year": 894, "time_original": "马殷先至关下后；具体日未载", "dynasty": "唐", "description": "马殷先到关下遣使联系蒋勋，蒋勋等以牛酒犒军。马殷使者称刘骧智勇、将十万精兵，又引术士预言并许归降富贵还乡。蒋勋等接受，说东军许他们返回；士卒欢呼，弃旗甲兵器散去。", "phases": [], "location_name": "龙回关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bf19e250-4a07-5972-a378-8c6fa176ff6f"}, {"title": "刘建锋前锋冒邵州兵入潭，擒斩邓处讷", "start_year": 894, "end_year": 894, "time_original": "龙回关守兵散去后；具体日未载", "dynasty": "唐", "description": "刘建锋让前锋穿守兵铠甲、举其旗奔潭州，潭人误当邵州兵返回，没有防备。刘军径入府，擒住正在宴饮的邓处讷并斩杀。", "phases": [], "location_name": "潭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "05205ad3-0f4f-532d-b364-879c09439e74"}, {"title": "刘建锋在潭州自称留后", "start_year": 894, "end_year": 894, "time_original": "894年五月戊辰", "dynasty": "唐", "description": "刘建锋取得潭州后自称留后。", "phases": [], "location_name": "潭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "70952dbe-0490-5ab9-879b-aa6f9275fc72"}, {"title": "彭州被围至相食，赵章出降", "start_year": 894, "end_year": 894, "time_original": "894年五月条；具体日未载", "dynasty": "唐", "description": "王建攻彭州，城中发生相食；彭州内外都指挥使赵章出城归降。", "phases": [], "location_name": "彭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "683a81a5-8ccd-5263-809c-6c407ecf26b4"}, {"title": "王先成请筑龙尾道接女墙", "start_year": 894, "end_year": 894, "time_original": "彭州攻城时；具体日未载", "dynasty": "唐", "description": "王先成建议筑龙尾道，连接城墙女墙。", "phases": [], "location_name": "彭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "14197e66-8e8d-5bdf-b5cc-ac6254cbb8ac"}, {"title": "西川兵登彭州，王茂权斩杨晟", "start_year": 894, "end_year": 894, "time_original": "894年五月丙子", "dynasty": "唐", "description": "西川军登上城墙，杨晟仍率众力战，刀子都虞候王茂权将其斩杀。", "phases": [], "location_name": "彭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5ccebcbe-90a4-5f76-a6e5-ecc092753ac8"}, {"title": "安师建被俘拒为王建将，遭杀后礼葬", "start_year": 894, "end_year": 894, "time_original": "彭州攻克后；具体日未载", "dynasty": "唐", "description": "彭州马步使安师建被俘，王建想用他为将；安师建说已誓与杨晟同生死，求速死。王建反复劝解，他不接受，于是被杀，获礼葬祭奠。", "phases": [], "location_name": "彭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c552ccbb-ca44-5bd1-b1ef-8645809c1493"}, {"title": "王建更赵章等四将姓名", "start_year": 894, "end_year": 894, "time_original": "彭州攻克后；具体日未载", "dynasty": "唐", "description": "王建将赵章改名王宗勉、王茂权改名宗训、王钊改名宗谨、李绾改姓名王宗绾。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "fcb7d8cb-9327-53aa-90cb-c834d1afc76b"}, {"title": "郑延昌罢相为右仆射", "start_year": 894, "end_year": 894, "time_original": "894年五月辛卯", "dynasty": "唐", "description": "中书侍郎、同平章事郑延昌罢去宰相职，任右仆射。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9f5f7898-525e-5b3c-9116-ea51e32e97db"}, {"title": "朱瑄朱瑾向河东求援", "start_year": 894, "end_year": 894, "time_original": "894年五月条；具体日未载", "dynasty": "唐", "description": "朱瑄、朱瑾向河东请求援兵。", "phases": [], "location_name": "兗、郓、河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0c8e19b3-033e-5134-abf3-9c8bf4d29487"}, {"title": "李克用遣安氏三将率五百骑经魏渡河援兗郓", "start_year": 894, "end_year": 894, "time_original": "894年五月条；具体日未载", "dynasty": "唐", "description": "李克用派骑将安福顺与其弟安福庆、安福迁率精骑五百，借道魏地渡河响应朱瑄朱瑾求援。", "phases": [], "location_name": "魏、河道、兗郓", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e3f5b689-8b6c-5ae2-94f3-9fa3fe696029"}, {"title": "杜洪攻黄州，杨行密遣朱延寿等救援", "start_year": 894, "end_year": 894, "time_original": "894年五月条；具体日未载", "dynasty": "唐", "description": "武昌节度使杜洪攻黄州，杨行密派行营都指挥使朱延寿等救援。", "phases": [], "location_name": "黄州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4e6781ec-13c5-51e6-a018-1d5c5f1c4ebc"}, {"title": "张廷范正式受任武宁节度使", "start_year": 894, "end_year": 894, "time_original": "894年六月甲午", "dynasty": "唐", "description": "朝廷应朱全忠的请求，以宋州刺史张廷范为武宁节度使。", "phases": [], "location_name": "武宁、宋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "14a20af1-91d8-53e6-b31d-0e464d0ae934"}]'::jsonb)
